package com.bank.core;

import java.math.BigDecimal;

// Abstract base class: shared state + shared concrete method + required abstract method.
public abstract class Account {
    protected final String accountId;
    protected final BigDecimal balance;

    protected Account(String accountId, BigDecimal balance) {
        this.accountId = accountId;
        this.balance = balance;
    }

    // Concrete, inherited by all subclasses.
    public BigDecimal balance() { return balance; }
    public String getAccountId() { return accountId; }

    // Abstract: no body — every concrete subclass MUST implement.
    public abstract BigDecimal monthlyInterest();

    // Concrete method that uses the abstract one (template method flavor).
    public BigDecimal projectedBalance() { return balance.add(monthlyInterest()); }
}
