package com.bank.core;

import java.math.BigDecimal;

public class SavingsAccount extends Account {
    private static final BigDecimal RATE = new BigDecimal("0.065");
    public SavingsAccount(String accountId, BigDecimal balance) { super(accountId, balance); }

    @Override
    public BigDecimal monthlyInterest() {
        return balance.multiply(RATE).divide(new BigDecimal("12"), 2, BigDecimal.ROUND_HALF_UP);
    }
}
