package com.bank.core;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class BaseVsAbstractDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Cannot instantiate the abstract base class directly:
        //   Account a = new Account("X", BigDecimal.ONE); // COMPILE ERROR

        // Concrete subclasses complete the template.
        List<Account> accounts = List.of(
            new SavingsAccount("SAV2001", new BigDecimal("1000000.00")),
            new CurrentAccount("CUR3001", new BigDecimal("250000.00"))
        );

        for (Account acc : accounts) {
            // Inherited concrete method + required abstract method via dynamic dispatch.
            log.info(() -> acc.getAccountId()
                    + " balance=" + acc.balance()
                    + " monthlyInterest=" + acc.monthlyInterest()
                    + " projected=" + acc.projectedBalance());
        }
    }
}
